{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "job_title": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Official job title. Prefer the job posting. If unavailable there, use provided job finder metadata. Otherwise null."
    },
    "company": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Company name. Prefer the job posting. If unavailable there, use provided job finder metadata. Otherwise null."
    },
    "location": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Actual job location. Prefer the job posting. If unavailable there, use provided job finder metadata. Otherwise null."
    },
    "remote_option": {
      "type": "string",
      "enum": [
        "On-site",
        "Hybrid",
        "Remote",
        "Unknown"
      ],
      "description": "Work location model. Prefer information from the posting. If unavailable, use provided job finder metadata. Return exactly On-site, Hybrid, Remote, or Unknown."
    },
    "home_office_available": {
      "anyOf": [
        { "type": "boolean" },
        { "type": "null" }
      ],
      "description": "True if home office is explicitly available, false if explicitly unavailable, otherwise null."
    },
    "employment_type": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Employment type. Prefer the job posting. If unavailable there, use provided job finder metadata. Otherwise null."
    },
    "weekly_hours": {
      "anyOf": [
        { "type": "number" },
        { "type": "null" }
      ],
      "description": "Weekly working hours as a number only if stated. Otherwise null."
    },
    "start_date": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Start date if stated. Otherwise null."
    },
    "required_technologies": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Technologies, programming languages, frameworks, databases, cloud platforms or technical tools that the candidate is explicitly expected or required to know. Return [] only if none can be identified."
    },
    "preferred_technologies": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Technologies, programming languages, frameworks or technical tools described as preferred, beneficial, advantageous, useful or nice-to-have. Return [] if none can be identified."
    },
    "required_requirements": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Mandatory non-technology requirements. Return [] if none are stated."
    },
    "preferred_requirements": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Optional, preferred or nice-to-have non-technology requirements. Return [] if none are stated."
    },
    "tasks": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Concrete responsibilities and tasks from the job. Extract technical responsibilities in particular. If a job finder description is provided, use it when the webpage content is incomplete."
    },
    "degree_fields": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Accepted or required fields of study. Return [] if none are stated."
    },
    "minimum_semester": {
      "anyOf": [
        { "type": "number" },
        { "type": "null" }
      ],
      "description": "Minimum university semester as a number if stated. Otherwise null."
    },
    "previous_work_experience_required": {
      "type": "boolean",
      "description": "True ONLY when actual previous professional work experience is explicitly mandatory. University projects, private projects, coursework, internships or first practical experience alone must NOT count as required professional work experience."
    },
    "required_experience": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Mandatory professional work experience requirement. Do not classify university projects, private projects or general first experience as professional work experience. Otherwise null."
    },
    "required_languages": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Languages explicitly required, including level when available. Return [] if none are stated."
    },
    "preferred_languages": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Languages explicitly preferred or optional. Return [] if none are stated."
    },
    "student_required": {
      "anyOf": [
        { "type": "boolean" },
        { "type": "null" }
      ],
      "description": "True if current university enrollment is explicitly required, false if explicitly not required, otherwise null."
    },
    "url": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Direct job URL provided in the input. Never invent a URL."
    },
    "source_url": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Source URL provided in the input. Never invent a URL."
    },
    "job_description": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Job description or factual job summary supplied by the job finder. Preserve it when provided."
    },
    "date_posted": {
      "anyOf": [
        { "type": "string" },
        { "type": "null" }
      ],
      "description": "Posting date supplied by the posting or job finder. Otherwise null."
    }
  },
  "required": [
    "job_title",
    "company",
    "location",
    "remote_option",
    "home_office_available",
    "employment_type",
    "weekly_hours",
    "start_date",
    "required_technologies",
    "preferred_technologies",
    "required_requirements",
    "preferred_requirements",
    "tasks",
    "degree_fields",
    "minimum_semester",
    "previous_work_experience_required",
    "required_experience",
    "required_languages",
    "preferred_languages",
    "student_required",
    "url",
    "source_url",
    "job_description",
    "date_posted"
  ]
}

